create extension if not exists pgcrypto;
create table if not exists public.workspaces(id uuid primary key default gen_random_uuid(),name text not null,created_at timestamptz default now());
create table if not exists public.workspace_members(workspace_id uuid references public.workspaces(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,role text not null check(role in('owner','tester')),primary key(workspace_id,user_id));
create table if not exists public.datasets(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,name text not null,notes text,row_count integer not null default 0,columns jsonb not null default '[]',rows jsonb not null default '[]',uploaded_by uuid references auth.users(id),created_at timestamptz default now());
create table if not exists public.tasks(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,title text not null,description text,status text not null default 'open' check(status in('open','progress','done')),priority text not null default 'normal' check(priority in('low','normal','high')),last_comment text,created_by uuid references auth.users(id),updated_by uuid references auth.users(id),created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.activity_log(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,actor_id uuid references auth.users(id),event_type text not null,details jsonb not null default '{}',created_at timestamptz default now());
create table if not exists public.feedback(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid references auth.users(id),feedback_type text not null check(feedback_type in('bug','confusing','idea','positive')),page_name text,message text not null,priority text not null default 'normal' check(priority in('low','normal','high')),created_at timestamptz default now());
create or replace function public.is_workspace_member(w uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.workspace_members m where m.workspace_id=w and m.user_id=auth.uid())$$;
create or replace function public.is_workspace_owner(w uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.workspace_members m where m.workspace_id=w and m.user_id=auth.uid() and m.role='owner')$$;
create or replace function public.touch_task() returns trigger language plpgsql as $$begin new.updated_at=now();return new;end$$;
drop trigger if exists task_touch on public.tasks;create trigger task_touch before update on public.tasks for each row execute function public.touch_task();
alter table public.workspaces enable row level security;alter table public.workspace_members enable row level security;alter table public.datasets enable row level security;alter table public.tasks enable row level security;alter table public.activity_log enable row level security;alter table public.feedback enable row level security;
create policy "workspace members read workspace" on public.workspaces for select to authenticated using(public.is_workspace_member(id));
create policy "member reads membership" on public.workspace_members for select to authenticated using(user_id=auth.uid() or public.is_workspace_owner(workspace_id));
create policy "members read datasets" on public.datasets for select to authenticated using(public.is_workspace_member(workspace_id));
create policy "members add datasets" on public.datasets for insert to authenticated with check(public.is_workspace_member(workspace_id) and uploaded_by=auth.uid());
create policy "owners and uploaders delete datasets" on public.datasets for delete to authenticated using(public.is_workspace_member(workspace_id) and (public.is_workspace_owner(workspace_id) or uploaded_by=auth.uid()));
grant delete on public.datasets to authenticated;
create policy "members read tasks" on public.tasks for select to authenticated using(public.is_workspace_member(workspace_id));
create policy "members add tasks" on public.tasks for insert to authenticated with check(public.is_workspace_member(workspace_id) and created_by=auth.uid());
create policy "members update tasks" on public.tasks for update to authenticated using(public.is_workspace_member(workspace_id)) with check(public.is_workspace_member(workspace_id) and updated_by=auth.uid());
create policy "owners delete tasks" on public.tasks for delete to authenticated using(public.is_workspace_owner(workspace_id));
create policy "members read activity" on public.activity_log for select to authenticated using(public.is_workspace_member(workspace_id));
create policy "members add activity" on public.activity_log for insert to authenticated with check(public.is_workspace_member(workspace_id) and actor_id=auth.uid());
create policy "members read feedback" on public.feedback for select to authenticated using(public.is_workspace_member(workspace_id));
create policy "members send feedback" on public.feedback for insert to authenticated with check(public.is_workspace_member(workspace_id) and user_id=auth.uid());